INSERT INTO overview.administrative_boundary(
  region_code,geometry,source_name,source_url,source_revision,source_license,
  source_feature_id,source_effective_on,geometry_sha256,source_dataset_id)
SELECT seed.region_code,seed.geometry,
       'geoBoundaries gbOpen CHN ADM3 (OpenStreetMap source)',
       'https://github.com/wmgeolab/geoBoundaries/tree/9469f09/releaseData/gbOpen/CHN/ADM3',
       '9469f09; build 2023-12-12; represented 2017; exact feature extract',
       'ODbL-1.0; open source; non-official survey product',
       seed.source_feature_id,NULL,
       encode(sha256(ST_AsEWKB(seed.geometry)),'hex'),
       'geoboundaries-chn-adm3-9469f09-qiqihar-2017'
  FROM qiqihar_open_boundary_seed seed;

INSERT INTO overview.administrative_boundary(
  region_code,geometry,source_name,source_url,source_revision,source_license,
  source_feature_id,source_effective_on,geometry_sha256,source_dataset_id)
SELECT '230200',city.geometry,
       'Derived union of 16 geoBoundaries Qiqihar county features',
       'https://github.com/wmgeolab/geoBoundaries/tree/9469f09/releaseData/gbOpen/CHN/ADM3',
       '9469f09; build 2023-12-12; represented 2017; exact county union',
       'ODbL-1.0; open source; non-official survey product',
       'derived-union:230200:16-counties',NULL,
       encode(sha256(ST_AsEWKB(city.geometry)),'hex'),
       'geoboundaries-chn-adm3-9469f09-qiqihar-2017'
  FROM (
    SELECT ST_Multi(ST_UnaryUnion(ST_Collect(geometry)))
             ::geometry(MultiPolygon,4326) geometry
      FROM qiqihar_open_boundary_seed
  ) city;

DO $$
DECLARE
  invalid_count integer;
  uncovered_count integer;
BEGIN
  SELECT count(*) FILTER(
           WHERE GeometryType(geometry)<>'MULTIPOLYGON'
              OR NOT ST_IsValid(geometry) OR ST_IsEmpty(geometry)
              OR ST_SRID(geometry)<>4326
              OR geometry_sha256<>encode(sha256(ST_AsEWKB(geometry)),'hex'))
    INTO invalid_count
    FROM overview.administrative_boundary
   WHERE region_code IN (
     '230200','230202','230203','230204','230205','230206','230207','230208',
     '230221','230223','230224','230225','230227','230229','230230','230231','230281'
   );
  SELECT count(*) INTO uncovered_count
    FROM overview.administrative_boundary child
    JOIN overview.administrative_boundary city ON city.region_code='230200'
   WHERE child.region_code<>'230200'
     AND child.source_dataset_id='geoboundaries-chn-adm3-9469f09-qiqihar-2017'
     AND NOT ST_CoveredBy(child.geometry,city.geometry);
  IF invalid_count<>0 OR uncovered_count<>0 THEN
    RAISE EXCEPTION
      'V160 persisted geometry gate failed: invalid %, uncovered %',
      invalid_count,uncovered_count;
  END IF;
END;
$$;

